def distance_k(root, target, k):
    parent, stack = {root: None}, [root]
    while stack:
        node = stack.pop()
        for child in (node.left, node.right):
            if child is not None:
                parent[child] = node
                stack.append(child)

    seen, ring = {target}, [target]
    for _ in range(k):
        nxt = []
        for node in ring:
            for nb in (node.left, node.right, parent[node]):
                if nb is not None and nb not in seen:
                    seen.add(nb)
                    nxt.append(nb)
        ring = nxt
    return sorted(n.val for n in ring)

def distance_k(root, target, k):
    out = []

    def collect(node, depth):
        if node is None or depth < 0:
            return
        if depth == 0:
            out.append(node.val)
            return
        collect(node.left, depth - 1)
        collect(node.right, depth - 1)

    def dfs(node):
        """Distance from node down to target, or -1 if not below."""
        if node is None:
            return -1
        if node is target:
            collect(node, k)
            return 0
        for here, other in ((node.left, node.right), (node.right, node.left)):
            d = dfs(here)
            if d != -1:
                if d + 1 == k:
                    out.append(node.val)
                else:
                    collect(other, k - d - 2)
                return d + 1
        return -1

    dfs(root)
    return sorted(out)
